create temp table _desc (category text, d text);
insert into _desc values
('smart-locks','قفل ذكي من RMP Tech بتصميم عصري وخامات متينة، يمنحك تحكماً كاملاً في الدخول لمنزلك أو مكتبك من الموبايل، مع سجل كامل لعمليات الفتح وإشعارات فورية. يتكامل مع أنظمة Zigbee و Wi-Fi لتشغيل مشاهد تلقائية عند فتح الباب.'),('hotel','حل فندقي متكامل للتحكم بالغرف بالكارت، يتكامل مع أنظمة إدارة الفنادق PMS ومفاتيح توفير الطاقة لرفع كفاءة التشغيل وتجربة النزيل.'),('access','وحدة تحكم بالدخول بتقنية RFID للمكاتب والمباني والمصاعد، بصلاحيات متعددة المستويات وتقارير حضور وانصراف.'),('accessories','إكسسوار أصلي لأنظمة الأقفال الذكية والتحكم بالدخول من RMP Tech.'),('sensors','حساس ذكي يراقب منزلك على مدار الساعة ويرسل لك تنبيهات فورية على الموبايل، ويمكن ربطه بالمشاهد التلقائية لتشغيل الإضاءة أو إغلاق المحابس أو تفعيل الإنذار.'),('switches','مفتاح إضاءة ذكي بواجهة زجاجية فاخرة، تتحكم فيه باللمس أو من التطبيق أو بالأوامر الصوتية، مع جدولة ومشاهد مخصصة لكل وقت.'),('modules','موديول ذكي صغير يُركب خلف المفتاح التقليدي ليحوله إلى مفتاح ذكي دون تغيير شكل الحائط.'),('knx','جهاز KNX معتمد للمشاريع الاحترافية، يوفر استقراراً عالياً وعمراً افتراضياً طويلاً، ويتكامل مع باقي منظومة KNX للإضاءة والستائر والتكييف والفنادق.'),('panels','شاشة تحكم مركزية تجمع كل أجهزة المنزل الذكي في مكان واحد: إضاءة، ستائر، تكييف، مشاهد وكاميرات.'),('gateways','البوابة هي قلب منظومة Zigbee؛ تربط كل الحساسات والمفاتيح والأقفال بالتطبيق وتتيح التحكم عن بُعد والمشاهد التلقائية.'),('breakers','قاطع كهربائي ذكي يتيح لك فصل وتوصيل الكهرباء عن بُعد ومراقبة الاستهلاك والحماية من الأحمال الزائدة.'),('curtains','حل ذكي للتحكم بالستائر بالتطبيق والريموت والأوامر الصوتية مع جدولة للفتح والإغلاق.');
insert into public.products (slug,name,model,sku,category,system,short_description,description,specs,price,compare_at_price,image_url,stock,featured)
select
  trim(both '-' from regexp_replace(lower(s.model||'-'||s.sku),'[^a-z0-9]+','-','g')),
  s.name, s.model, s.sku, s.category, s.system,
  (case s.system when 'wifi' then 'يعمل بالواي فاي مباشرة عبر تطبيق Tuya / Smart Life' when 'zigbee' then 'يعمل ببروتوكول Zigbee 3.0 مع بوابة RMP' when 'knx' then 'جهاز KNX معتمد للمشاريع الاحترافية' else 'يعمل بشكل مستقل بتقنية RFID' end) || ' — موديل ' || s.model,
  d.d,
  jsonb_build_array(
    jsonb_build_object('label','الموديل','value',s.model),
    jsonb_build_object('label','كود المنتج','value',s.sku),
    jsonb_build_object('label','البروتوكول','value',case s.system when 'wifi' then 'واي فاي (تطبيق Tuya / Smart Life)' when 'zigbee' then 'Zigbee 3.0' when 'knx' then 'KNX TP' else 'مستقل / RFID' end)
  ) || replace(sp.s::text,'__G__',s.gang::text)::jsonb,
  s.price, s.cmp, '/__l5e/assets-v1/'||s.aid||'/rmp-'||lpad(s.i::text,3,'0')||'.jpg', s.stock, s.featured
from _seed s
join _skey k on k.i=s.i
join _spec sp on sp.k=k.k
join _desc d on d.category=s.category
order by s.i;